from collections import Counter

def count_by_level(path):
    counts = Counter()
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parts = line.split(maxsplit=2)
            if len(parts) < 2:
                continue  # skip malformed lines
            level = parts[1]
            counts[level] += 1
    return counts


