from collections import deque

def rolling_average(nums, w):
    if w <= 0:
        raise ValueError("w must be positive")
    window = deque()
    running_sum = 0.0
    averages = []
    for x in nums:
        window.append(x)
        running_sum += x
        if len(window) > w:
            running_sum -= window.popleft()
        if len(window) == w:
            averages.append(running_sum / w)
    return averages


if __name__ == "__main__":
    print(rolling_average([1, 2, 3, 4, 5], 3))  # [2.0, 3.0, 4.0]

