from collections import deque

def sliding_window_max(nums, w):
    dq = deque()  # holds indices, values decreasing
    result = []
    for i, x in enumerate(nums):
        while dq and nums[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - w:
            dq.popleft()
        if i >= w - 1:
            result.append(nums[dq[0]])
    return result


