def flatten_json(obj, sep="."):
    items = {}
    stack = [("", obj)]
    while stack:
        prefix, cur = stack.pop()
        for k, v in cur.items():
            nk = f"{prefix}{sep}{k}" if prefix else k
            if isinstance(v, dict):
                stack.append((nk, v))
            else:
                items[nk] = v
    return items

