def find_late_events(events, allowed_lateness=0):
    max_ts = None
    late = []
    for event in events:
        ts = event["timestamp"]
        if max_ts is not None and ts < max_ts - allowed_lateness:
            late.append(event)
        if max_ts is None or ts > max_ts:
            max_ts = ts
    return late


if __name__ == "__main__":
    stream = [
        {"id": "a", "timestamp": 10},
        {"id": "b", "timestamp": 12},
        {"id": "c", "timestamp": 9},   # late
        {"id": "d", "timestamp": 13},
        {"id": "e", "timestamp": 11},  # late
    ]
    print([e["id"] for e in find_late_events(stream)])  # ['c', 'e']
